import uuid, httpx
from tenacity import retry, retry_if_exception, stop_after_attempt, wait_random_exponential

def retryable(exc: BaseException) -> bool:
    if isinstance(exc, httpx.TransportError):            # timeouts and dropped connections
        return True
    return isinstance(exc, httpx.HTTPStatusError) and (
        exc.response.status_code == 429 or exc.response.status_code >= 500)

@retry(retry=retry_if_exception(retryable),
       wait=wait_random_exponential(multiplier=0.5, max=8),   # full jitter, capped at 8 s
       stop=stop_after_attempt(4), reraise=True)
def post_refund(client: httpx.Client, body: dict, key: str) -> dict:
    r = client.post("/v1/refunds", json=body, headers={"Idempotency-Key": key}, timeout=10.0)
    r.raise_for_status()
    return r.json()

def refund(client: httpx.Client, dispute_id: str, amount_paise: int) -> dict:
    # One key per logical action, derived from the dispute, so every retry reuses it
    key = str(uuid.uuid5(uuid.NAMESPACE_URL, f"refund/{dispute_id}"))
    return post_refund(client, {"dispute_id": dispute_id, "amount": amount_paise}, key)

import hashlib, json, redis
r = redis.Redis()

def handle_refund(key: str, body: dict):
    fp = hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()
    slot = f"idem:{key}"
    if not r.set(slot, json.dumps({"fp": fp, "state": "running"}), nx=True, ex=86_400):
        rec = json.loads(r.get(slot))
        if rec["fp"] != fp:
            return 422, {"error": "Idempotency-Key reused with a different payload"}
        if rec["state"] == "running":
            return 409, {"error": "A request with this key is still being processed"}
        return rec["status"], rec["body"]                # replay the first response
    status, resp = do_refund(body)
    r.set(slot, json.dumps({"fp": fp, "state": "done", "status": status, "body": resp}), ex=86_400)
    return status, resp

